CAMPO_IDADE = "idade"
CAMPO_DATA_HORA = "data_hora_envio"
FORMATO_DATA_HORA = "dd/MM/yyyy HH:mm:ss"

# Faixa plausivel de idade para populacao economicamente ativa respondendo
# a pesquisa (usada so como guarda-corpo; nos dados reais nao ha violacao,
# mas mantem a Silver protegida contra erro de digitacao/importacao futuro)
IDADE_MINIMA_PLAUSIVEL = 14
IDADE_MAXIMA_PLAUSIVEL = 100

TABELAS = {
    "2023": "state_of_data_2023",
    "2024": "state_of_data_2024",
    "2025-2026": "state_of_data_2025_2026",
}

# =========================================================================
# PROCESSAMENTO POR ANO
# =========================================================================
for ano, nome_tabela in TABELAS.items():
    print(f"--- Processando ano {ano} ---")

    # 1. Ler DIRETO do S3 (Bronze), nao via Data Catalog.
    #    Motivo (achado #11 do log de qualidade): o Crawler nao detectou
    #    corretamente a linha de cabecalho em nenhuma das 3 bases -- catalogou
    #    com nomes genericos (col0, col1...) e "vazou" o header como se fosse
    #    uma linha de dado. Lendo direto do S3 com header=True, o Spark
    #    interpreta a primeira linha corretamente, igual o Pandas fez localmente.
    caminho_bronze = f"s3://{BUCKET}/Bronze/state-of-data-{ano}/"
    df = spark.read.option("header", "true").option("inferSchema", "false").csv(caminho_bronze)

    # 2. Selecionar + renomear todas as colunas de negocio mapeadas para este ano
    selecoes = []
    for nome_padronizado, colunas_por_ano in MAPEAMENTO.items():
        col_original = colunas_por_ano.get(ano)
        if col_original is not None and col_original in df.columns:
            selecoes.append(col(f"`{col_original}`").alias(nome_padronizado))
        else:
            # Campo nao existe nesse ano -> preenche com valor nulo tipado,
            # para manter o mesmo schema entre os 3 anos na Silver
            selecoes.append(lit(None).cast("string").alias(nome_padronizado))

    df_silver = df.select(*selecoes)

    # 3. Adicionar coluna de rastreabilidade (de qual pesquisa/ano veio o registro)
    df_silver = df_silver.withColumn("ano_pesquisa", lit(ano))

    # 4. Remover linhas onde TODOS os campos de negocio estao vazios
    campos_negocio = list(MAPEAMENTO.keys())
    df_silver = df_silver.dropna(how="all", subset=campos_negocio)

    # 5. Remover registros duplicados (linha inteira identica em todos os
    #    campos de negocio -- nao considera ano_pesquisa, ja que duas
    #    respostas identicas em anos diferentes sao pessoas diferentes)
    linhas_antes = df_silver.count()
    df_silver = df_silver.dropDuplicates(subset=campos_negocio)
    linhas_depois = df_silver.count()
    print(f"  [{ano}] Duplicatas removidas: {linhas_antes - linhas_depois}")

    # 6. Padronizar tipos de dados (texto -> inteiro/timestamp)
    #    6a. Campos de multipla escolha (checkbox): "0.0"/"1.0" -> inteiro 0/1
    for campo in CAMPOS_FLAG_BINARIO:
        if campo in df_silver.columns:
            df_silver = df_silver.withColumn(campo, col(campo).cast("double").cast("int"))

    #    6b. Idade: texto -> inteiro
    df_silver = df_silver.withColumn(CAMPO_IDADE, col(CAMPO_IDADE).cast("int"))

    #    6c. Data/hora de envio: texto -> timestamp
    if CAMPO_DATA_HORA in df_silver.columns:
        df_silver = df_silver.withColumn(
            CAMPO_DATA_HORA, to_timestamp(col(CAMPO_DATA_HORA), FORMATO_DATA_HORA)
        )

    # 7. Tratar anomalias: idade fora da faixa plausivel vira nulo
    #    (guarda-corpo de qualidade; nos dados atuais nenhum registro viola isso)
    df_silver = df_silver.withColumn(
        CAMPO_IDADE,
        when(
            (col(CAMPO_IDADE) >= IDADE_MINIMA_PLAUSIVEL) & (col(CAMPO_IDADE) <= IDADE_MAXIMA_PLAUSIVEL),
            col(CAMPO_IDADE)
        ).otherwise(lit(None).cast("int"))
    )

    # 8. Tratamento pontual: normalizar espacos duplicados em faixa_salarial
    if "faixa_salarial" in df_silver.columns:
        df_silver = df_silver.withColumn(
            "faixa_salarial",
            regexp_replace(trim(col("faixa_salarial")), r"\s+", " ")
        )

    # 9. Validacao antes de gravar
    total_linhas = df_silver.count()
    print(f"  [{ano}] Silver pronta: {total_linhas} linhas x {len(df_silver.columns)} colunas")
    df_silver.printSchema()
    df_silver.show(5, truncate=40)

    # 10. Gravar na camada Silver (Parquet), particionado por ano de pesquisa
    caminho_silver = f"s3://{BUCKET}/Silver/state-of-data-{ano}/"
    df_silver.write.mode("overwrite").parquet(caminho_silver)
    print(f"  [{ano}] Gravado em: {caminho_silver}")

job.commit()
